),
resolved AS (
  SELECT s.*, c.id AS category_id
  FROM seed s
  JOIN public.categories c ON c.slug = s.category_slug
),
inserted_products AS (
  INSERT INTO public.products (
    id, name, description, base_price, image_url,
    gender_id, category_id, created_at, slug, material
  )
  SELECT
    gen_random_uuid(), s.name, s.description, s.base_price,
    jsonb_build_array(s.image_url), s.gender_id, s.category_id,
    CURRENT_TIMESTAMP, s.slug, s.material
  FROM resolved s
  WHERE NOT EXISTS (
    SELECT 1 FROM public.products p WHERE p.slug = s.slug
  )
  RETURNING id, slug, base_price, image_url, category_id
),
updated_products AS (
  UPDATE public.products p
  SET name = s.name,
      description = s.description,
      image_url = jsonb_build_array(s.image_url)
  FROM resolved s
  WHERE p.slug = s.slug AND p.category_id = s.category_id
  RETURNING p.id, p.slug, p.base_price, p.image_url, p.category_id
),
affected_products AS (
  SELECT * FROM inserted_products
  UNION ALL
  SELECT * FROM updated_products
),
inserted_variants AS (
  INSERT INTO public.product_variants (
    id, product_id, size, color, price, stock, sku, created_at
  )
  SELECT
    gen_random_uuid(), p.id, sizes.size, palette.color,
    p.base_price, 20,
    'PRD-' || REPLACE(p.id::text, '-', '')
      || '-CLR-' || md5(palette.color) || '-' || sizes.size,
    CURRENT_TIMESTAMP
  FROM affected_products p
  JOIN resolved s ON s.slug = p.slug AND s.category_id = p.category_id
  CROSS JOIN LATERAL unnest(s.colors) AS palette(color)
  CROSS JOIN (VALUES ('S'), ('M'), ('L'), ('XL')) AS sizes(size)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.product_variants v
    WHERE v.product_id = p.id
      AND v.size = sizes.size AND v.color = palette.color
  )
  RETURNING id
)
SELECT
  (SELECT COUNT(DISTINCT category_slug) FROM resolved) AS matched_categories,
  (SELECT COUNT(*) FROM inserted_products) AS added_products,
  (SELECT COUNT(*) FROM updated_products) AS updated_products,
  (SELECT COUNT(*) FROM affected_products) AS total_seed_products,
  (SELECT COUNT(DISTINCT image_url ->> 0)
   FROM affected_products) AS unique_primary_images,
  (SELECT COUNT(*) FROM inserted_variants) AS added_variants,
  COALESCE((
    SELECT jsonb_agg(m.category_slug ORDER BY m.category_slug)
    FROM (
      SELECT DISTINCT s.category_slug FROM seed s
      WHERE NOT EXISTS (
        SELECT 1 FROM public.categories c WHERE c.slug = s.category_slug
      )
    ) m
  ), '[]'::jsonb) AS missing_category_slugs,
  COALESCE((
    SELECT jsonb_agg(s.slug ORDER BY s.slug)
    FROM resolved s
    WHERE NOT EXISTS (
      SELECT 1 FROM affected_products p WHERE p.slug = s.slug
    )
  ), '[]'::jsonb) AS skipped_product_slugs;
